const routeBySkill: Record<LevelSkillSlug, SkillModule['route']> = {
  listening: '/listening', reading: '/reading', writing: '/writing', speaking: '/speaking',
  understanding: '/understanding', vocabulary: '/vocabulary', 'yki-test': '/yki-test',
}

function nativeMeaning(term: string, fallback?: string) {
  const headword = term.toLowerCase().replace(/[.,!?;:]/g, '').trim()
  const entry = searchDictionary(headword, 'fi')[0]
  if (entry?.definitions[0]?.definitionNative) return entry.definitions[0].definitionNative
  if (fallback && !looksEnglish(fallback)) return fallback
  return 'Harjoittele ilmausta asiayhteydessä ja muodosta sillä oma lause.'
}

function looksEnglish(value: string) {
  const normalized = ` ${value.toLowerCase()} `
  const markers = [
    ' the ', ' a ', ' an ', ' to ', ' of ', ' in ', ' on ', ' is ', ' are ', ' i ', ' you ', ' we ', ' they ',
    'this ', 'that ', 'with ', 'for ', 'from ', 'open', 'closed', 'choose', 'write', 'listen', 'time of day',
    'place', 'person', 'home', 'water', 'friend', 'hello', 'thank you', 'bus stop', 'shopping list', 'student',
    'teacher', 'morning', 'work', 'job', 'read ', 'speak ', 'understand ', 'because ', 'formal ', 'informal ',
  ]
  return markers.some(marker => normalized.includes(marker))
}

function nativeExamples(seed: LessonSeed) {
  return seed.examples.map(example => ({
    ...example,
    target: example.note && !looksEnglish(example.note)
      ? example.note
      : nativeMeaning(example.source, example.target),
  }))
}

function nativeFlashcards(seed: LessonSeed) {
  return seed.flashcards.map(card => ({ front: card.front, back: nativeMeaning(card.front, card.back) }))
}

function buildNativeChecks(seed: LessonSeed) {
  const examples = nativeExamples(seed)
  const cards = nativeFlashcards(seed)
  const first = cards[0] ?? { front: seed.title, back: seed.subtitle }
  const second = cards[1] ?? first
  const third = cards[2] ?? second
  return [
    {
      question: 'Valitse sana tai ilmaus, joka kuuluu tähän oppituntiin.',
      options: [first.front, 'satunnainen sana', 'aiheeseen kuulumaton ilmaus'],
      answer: first.front,
      explanation: `“${first.front}” kuuluu tämän oppitunnin aiheeseen: ${seed.title}.`,
    },
    {
      question: 'Valitse tämän oppitunnin mallilause tai malliesimerkki.',
      options: [examples[0]?.source ?? first.front, 'Tämä lause ei kuulu tähän oppituntiin.', 'Tässä ei käytetä oppitunnin aihetta.'],
      answer: examples[0]?.source ?? first.front,
      explanation: `Malliesimerkki liittyy suoraan aiheeseen: ${seed.title}.`,
    },
    {
      question: 'Mikä näistä kuuluu tämän oppitunnin sanastoon?',
      options: [second.front, third.front === second.front ? 'toinen aihe' : third.front, 'ei tämän oppitunnin sana'],
      answer: second.front,
      explanation: `“${second.front}” on tämän oppitunnin harjoiteltava sana tai ilmaus.`,
    },
  ]
}

function boardFor(level: LearningLevelId, skill: LevelSkillSlug, seed: LessonSeed): SkillModule['blackboard'] {
  const theme = levelThemes[level]
  const examples = nativeExamples(seed)
  const first = examples[0]
  const second = examples[1] ?? examples[0]
  return [
    { type: 'note', title: `${level.toUpperCase()} · päivän tavoite`, body: `${theme.focus}. ${seed.learn[0]}` },
    { type: 'compare', title: skill === 'understanding' ? 'Rakenne käytössä' : 'Malliesimerkki', leftLabel: 'Suomi', left: first.source, rightLabel: 'Selitys / huomio', right: first.target },
    { type: 'table', title: 'Muista nämä', rows: [[theme.grammar, 'Rakenne'], [theme.register, 'Rekisteri'], [second.source, second.target]] },
  ]
}

export function getLevelSkillModule(level: LearningLevelId, skill: LevelSkillSlug): SkillModule {
  const seed = curriculum[level][skill]
  const examples = nativeExamples(seed)
  const flashcards = nativeFlashcards(seed)
  const checks = buildNativeChecks(seed)
  return {
    route: routeBySkill[skill],
    title: seed.title,
    subtitle: seed.subtitle,
    levelRange: level.toUpperCase(),
    learn: seed.learn,
    examples,
    blackboard: boardFor(level, skill, seed),
    flashcards,
    practice: checks.slice(0, 2),
    test: checks,
  }
}

